import{_ as t,o as a,c as o,ah as s}from"./chunks/framework.ChH6X6u6.js";const y=JSON.parse('{"title":"Payroll","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/paie.md","filePath":"src/en/guide/admin/paie.md"}'),n={name:"en/guide/admin/paie.md"};function r(l,e,i,p,h,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="payroll" tabindex="-1">Payroll <a class="header-anchor" href="#payroll" aria-label="Permalink to &quot;Payroll&quot;">​</a></h1><p>The <strong>Staff → Payroll</strong> page prepares the month&#39;s payslips. Only administrators see it, and only if your licence includes the <strong>Human resources</strong> module.</p><p>The payslip stays simple: a base salary, plus allowances, minus deductions, all entered by hand. ERA does <strong>not</strong> compute social security contributions or income tax: if you withhold them, add them as deductions, with the amount your accountant worked out.</p><h2 id="before-the-first-payroll-the-base-salary" tabindex="-1">Before the first payroll: the base salary <a class="header-anchor" href="#before-the-first-payroll-the-base-salary" aria-label="Permalink to &quot;Before the first payroll: the base salary&quot;">​</a></h2><p>Every paid employee needs a <strong>Monthly base salary</strong> on their record (see <a href="/era-guide/en/guide/admin/personnel-utilisateurs.html#manage-staff-records-and-contracts">Staff and user accounts</a>). The field is optional: an employee without a base salary gets no payslip.</p><p>Under <strong>Employees without a base salary</strong>, the Payroll page lists the active employees who lack this amount. <strong>Open the employee files</strong> leads to the list to fill it in.</p><h2 id="preparing-the-month-s-payroll" tabindex="-1">Preparing the month&#39;s payroll <a class="header-anchor" href="#preparing-the-month-s-payroll" aria-label="Permalink to &quot;Preparing the month&#39;s payroll&quot;">​</a></h2><ol><li>Under <strong>Prepare a payroll</strong>, choose the <strong>Month</strong> (the month after the latest payroll is suggested).</li><li>Click <strong>Prepare the payroll</strong>.</li></ol><p>ERA creates a payslip for each <strong>active</strong> employee with a base salary. The payslip keeps the employee&#39;s name, position and site at that moment, and their current base salary.</p><p>The allowances and deductions on each employee&#39;s latest payslip are <strong>carried over</strong>: a monthly transport allowance, or an advance paid back over several months, does not have to be typed again. Remove the ones that no longer apply this month.</p><p>A month can only be prepared once. To start over, delete the draft (see below).</p><h2 id="adjusting-the-payslips" tabindex="-1">Adjusting the payslips <a class="header-anchor" href="#adjusting-the-payslips" aria-label="Permalink to &quot;Adjusting the payslips&quot;">​</a></h2><p>While the payroll is a <strong>Draft</strong>, each row of the table has an <strong>Edit</strong> button:</p><ol><li>If needed, correct this month&#39;s <strong>Base salary</strong>.</li><li>Click <strong>Add an allowance</strong> or <strong>Add a deduction</strong>, then enter the <strong>Label</strong> (for example &quot;Housing allowance&quot;, &quot;Salary advance&quot;) and the <strong>Amount</strong>, in FCFA.</li><li>Remove a line with the bin icon.</li><li>Check the <strong>Net pay</strong> shown at the bottom, then click <strong>Save</strong>.</li></ol><p>Net pay is the base salary, plus the allowances, minus the deductions. The table shows, for each employee, the base salary, allowances, deductions and net, with the month&#39;s total.</p><p>Changing a payslip&#39;s base salary does not change the employee&#39;s record: for a lasting raise, update the record too.</p><h2 id="closing-the-payroll" tabindex="-1">Closing the payroll <a class="header-anchor" href="#closing-the-payroll" aria-label="Permalink to &quot;Closing the payroll&quot;">​</a></h2><p>Once the salaries are paid, click <strong>Close the payroll</strong> and confirm. The payroll becomes <strong>Closed</strong>:</p><ul><li>the payslips can no longer be changed;</li><li>each employee can download theirs from <strong>My payslips</strong> (see below).</li></ul><p>To fix a mistake after closing, click <strong>Reopen</strong>: the payslips can be edited again and disappear from the employees&#39; space until the next closing.</p><p>A draft payroll can also be <strong>deleted</strong>, with all its payslips. A closed payroll must be reopened first.</p><h2 id="printing-and-exporting" tabindex="-1">Printing and exporting <a class="header-anchor" href="#printing-and-exporting" aria-label="Permalink to &quot;Printing and exporting&quot;">​</a></h2><p>From the month&#39;s payroll:</p><table tabindex="0"><thead><tr><th>Button</th><th>Content</th></tr></thead><tbody><tr><td>All payslips (PDF)</td><td>one payslip per page, to print and have signed</td></tr><tr><td>PDF (on a row)</td><td>a single employee&#39;s payslip</td></tr><tr><td>Payroll statement (CSV)</td><td>one row per employee: position, site, base salary, allowances, gross, deductions, net, total</td></tr><tr><td>Accounting entries (CSV)</td><td>the month&#39;s payroll entries, to bring into your accounting software</td></tr></tbody></table><p>While the payroll is a draft, the PDF payslips are marked &quot;Brouillon&quot; (draft).</p><h3 id="accounting-entries" tabindex="-1">Accounting entries <a class="header-anchor" href="#accounting-entries" aria-label="Permalink to &quot;Accounting entries&quot;">​</a></h3><p>Entries are dated the last day of the month, in the <strong>PA</strong> journal. For each employee:</p><ul><li>net pay: debit <strong>661100</strong> (staff pay), credit <strong>422000</strong> (staff, pay due);</li><li>deductions, if any: debit <strong>661100</strong>, credit <strong>428000</strong> (staff, accrued charges).</li></ul><p>These accounts follow the SYSCOHADA chart. Have your accountant confirm them: to change them, contact edPage.</p><h2 id="my-payslips-employees" tabindex="-1">My payslips (employees) <a class="header-anchor" href="#my-payslips-employees" aria-label="Permalink to &quot;My payslips (employees)&quot;">​</a></h2><p>Any staff member with an employee record finds their payslips under <strong>Staff → My payslips</strong>: the month, gross, deductions and net, with <strong>Download</strong> for the PDF.</p><p>Only <strong>closed</strong> months appear there. An employee only sees their own payslips.</p><p>If the account is not linked to an employee record, the page says so: the administration must create the record.</p>',33)])])}const g=t(n,[["render",r]]);export{y as __pageData,g as default};
